import express from 'express';
import { getCustomer, createOrUpdateCustomer } from '../services/dualWriteService.js';
import { featureFlag } from '../utils/featureFlag.js';
import { logger } from '../utils/logger.js';
const router = express.Router();

router.get('/:id', async (req, res) => {
  try {
    const readFromMongo = featureFlag.isEnabled('read_from_mongo');
    const customer = await getCustomer(req.params.id, readFromMongo);
    res.json(customer);
  } catch (err) {
    logger.error('Error fetching customer', err);
    res.status(500).json({ message: 'Internal Server Error' });
  }
});

router.post('/', async (req, res) => {
  try {
    const result = await createOrUpdateCustomer(req.body);
    res.json(result);
  } catch (err) {
    logger.error('Error creating/updating customer', err);
    res.status(500).json({ message: 'Internal Server Error' });
  }
});

export default router;

import express from 'express';
