import { postgresService } from './postgresService.js';
import { mongoService } from './mongoService.js';
import { featureFlag } from '../utils/featureFlag.js';
import { logger } from '../utils/logger.js';
import { validateSchema } from '../utils/schemaValidator.js';

export async function getCustomer(id, readFromMongo = false) {
  return readFromMongo ? await mongoService.getCustomerById(id) : await postgresService.getCustomerById(id);
}

export async function createOrUpdateCustomer(data) {
  validateSchema(data);
  const dualWriteEnabled = featureFlag.isEnabled('dual_write');
  const pgResult = await postgresService.upsertCustomer(data);
  if (dualWriteEnabled) {
    try {
      await mongoService.upsertCustomer(data);
    } catch (err) {
      logger.error('Mongo dual-write failed', err);
    }
  }
  return { id: pgResult.id, status: 'success' };
}

import { postgresService } from './postgresService.js';
import { mongoService } from './mongoService.js';
import { logger } from '../utils/logger.js';

export async function validateParity() {
  let mismatches = 0;
  const postgresRecords = await postgresService.getAllCustomers();
  for (let record of postgresRecords) {
    const mongoRecord = await mongoService.getCustomerById(record.id);
    if (!mongoRecord || JSON.stringify(mongoRecord) !== JSON.stringify(record)) {
      mismatches++;
    }
  }
  const status = mismatches === 0 ? 'success' : 'mismatch_found';
  logger.info(`Validation completed: ${mismatches} mismatches`);
  return { total_records_compared: postgresRecords.length, mismatches_found: mismatches, status };
}

import { featureFlag } from '../utils/featureFlag.js';
import { logger } from '../utils/logger.js';

export async function rollbackToPostgres(reason) {
  try {
    featureFlag.disable('read_from_mongo');
    featureFlag.disable('dual_write');
    logger.warn(`Rollback initiated: ${reason}`);
    return { status: 'success', message: 'Traffic reverted to PostgreSQL within one hour' };
  } catch (err) {
    logger.error('Rollback failed', err);
    return { status: 'error', message: 'Rollback process encountered an error' };
  }
}

import LaunchDarkly from 'launchdarkly-node-server-sdk';
import { logger } from './logger.js';
const ldClient = LaunchDarkly.init(process.env.LAUNCHDARKLY_SDK_KEY);
await ldClient.waitForInitialization();

export const featureFlag = {
  async isEnabled(flagName) {
    try {
      return await ldClient.variation(flagName, { key: 'system' }, false);
    } catch (err) {
      logger.error('Feature flag error', err);
      return false;
    }
  },
  disable(flagName) {
    logger.warn(`Feature flag ${flagName} should be disabled manually via dashboard.`);
  }
};

import { MongoClient } from 'mongodb';
import { logger } from '../utils/logger.js';
const client = new MongoClient(process.env.MONGODB_URI);
await client.connect();
const db = client.db('customers_db');
const collection = db.collection('customers');

export const mongoService = {
  async getCustomerById(id) {
    return await collection.findOne({ _id: id });
  },
  async upsertCustomer(data) {
    await collection.updateOne({ _id: data.id }, { $set: data }, { upsert: true });
  },
  async getAllCustomers() {
    return await collection.find({}).toArray();
  }
};

import pkg from 'pg';
import { logger } from '../utils/logger.js';
const { Pool } = pkg;
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

export const postgresService = {
  async getCustomerById(id) {
    const res = await pool.query('SELECT * FROM customers WHERE id = $1', [id]);
    return res.rows[0];
  },
  async upsertCustomer(data) {
    const res = await pool.query('INSERT INTO customers (id, name, country) VALUES ($1, $2, $3) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, country = EXCLUDED.country RETURNING id', [data.id, data.name, data.country]);
    return res.rows[0];
  },
  async getAllCustomers() {
    const res = await pool.query('SELECT * FROM customers');
    return res.rows;
  }
};

