import Ajv from 'ajv';
const ajv = new Ajv();
const schema = {
  type: 'object',
  properties: {
    id: { type: 'string' },
    name: { type: 'string' },
    country: { type: 'string' },
    fields: { type: 'object' }
  },
  required: ['name', 'country']
};
const validate = ajv.compile(schema);
export function validateSchema(data) {
  if (!validate(data)) throw new Error('Invalid customer schema');
}
